"""Self-contained offline explorer, with no external scripts or row identifiers."""
import html
import json
from .analysis import records


def create(listings, config, results, path):
    data = records(listings[["neighbourhood", "room_type", "price", "review_scores_rating", "unavailable_share"]])
    payload = json.dumps(data, allow_nan=False).replace("<", "\\u003c")
    title = html.escape(config["display_name"])
    price_note = "Calendar prices are absent in this snapshot, so seasonal prices and revenue cannot be measured." if not any(x["priced_days"] for x in results["calendar_months"]) else "Calendar prices, where available, are advertised quotes, not transaction revenue."
    text = TEMPLATE.replace("USD", config["currency"]).replace("__TITLE__", title).replace("__DATE__", config["snapshot_date"]).replace("__DATA__", payload).replace("__PRICE_NOTE__", price_note)
    path.write_text(text, encoding="utf-8")


